WITH transactions_by_account AS (SELECT account_id, COUNT(DISTINCT amount) AS unique_merchants, CONCAT_WS(', ', SORT_ARRAY(COLLECT_SET(merchant))) AS merchant_values FROM transactions GROUP BY account_id) SELECT a.id, a.status, a.account_type, tba.unique_merchants, tba.merchant_values FROM accounts a JOIN transactions_by_account tba ON a.id = tba.account_id WHERE tba.unique_merchants >= 6
